let username = msg.payload.wasos_username;
let password = msg.payload.wasos_password;

let auth = Buffer.from(username + ":" + password).toString("base64");

msg.headers = {
    "Authorization": "Basic " + auth
};

msg.url = global.get("parat_bridge").base_urls.wasos + "/apisec/login";

// Carry username, chatroom and optional sender through the login flow
msg.config = {
    username: username,
    chatroom_name: msg.payload.wasos_chatroom_name,
    sender_name: msg.payload.wasos_sender_name
};

return msg;

// Network or connection error — HTTP node forwarded it as a message
if (msg.error) {
    node.error("WaSOS login request failed: " + msg.error.message, msg);
    return null;
}

// Non-200 response — bad credentials or server-side problem
if (msg.statusCode !== 200) {
    const detail = msg.payload?.message || msg.payload?.error || JSON.stringify(msg.payload);
    node.error("WaSOS login rejected (HTTP " + msg.statusCode + "): " + detail, msg);
    return null;
}

// 200 OK but nonce field is absent — unexpected API change or malformed response
if (!("nonce" in (msg.payload ?? {}))) {
    node.error("WaSOS login succeeded (HTTP 200) but response contains no nonce field. Payload: " + JSON.stringify(msg.payload), msg);
    return null;
}

// Nonce field present but empty — API returned the field with no value
if (!msg.payload.nonce || typeof msg.payload.nonce !== "string" || msg.payload.nonce.trim() === "") {
    node.error("WaSOS login succeeded (HTTP 200) but nonce is empty or invalid. Got: " + JSON.stringify(msg.payload.nonce), msg);
    return null;
}

node.log("WaSOS login successful for user '" + msg.config.username + "' — nonce received.");
return msg;
